#!/usr/bin/env python3
"""
Extract frames from videos based on H5 file

Supports: OVP, YouTube datasets

This script:
1. Reads the H5 file to get the number of frames for each video
2. Extracts frames from videos at the same rate as the features
3. Saves frames to datasets_preprocessed/data/dataset/{DATASET}/frames/{video_id}/
"""

import os
import cv2
import h5py
import argparse
import shutil
from pathlib import Path
from tqdm import tqdm
import numpy as np

# YouTube dataset video mapping (generated by duration matching assuming 2fps sampling)
# Maps H5 video_N to actual video file vM
YOUTUBE_VIDEO_MAPPING = {
    11: 71, 12: 75, 13: 73, 14: 74, 15: 81, 16: 100, 17: 88, 18: 78, 19: 79, 20: 80,
    21: 90, 23: 83, 24: 84, 25: 85, 26: 86, 27: 99, 28: 98, 29: 89, 30: 102, 31: 91,
    32: 92, 33: 93, 34: 94, 35: 95, 36: 96, 37: 110, 38: 77, 39: 76, 40: 16, 41: 101,
    42: 106, 43: 107, 44: 104, 45: 105, 46: 19, 47: 103, 48: 108, 49: 109, 50: 82,
}


def clear_frames_directory(frames_dir, force=False):
    """
    Clear all existing frames in the output directory

    Args:
        frames_dir: Path to frames directory to clear
        force: If True, skip confirmation prompt (for automated runs)
    """
    frames_dir = Path(frames_dir)

    if not frames_dir.exists():
        print(f"📂 Frames directory doesn't exist yet: {frames_dir}")
        return

    print(f"🗑️  Clearing frames directory: {frames_dir}")

    # Count existing frames
    video_dirs = list(frames_dir.glob("video_*"))
    total_frames = sum(len(list(v.glob("*.jpg"))) for v in video_dirs)

    if total_frames == 0:
        print(f"   No frames to clear")
        return

    print(f"   Found {len(video_dirs)} video directories with {total_frames} frames")

    # Ask for confirmation (unless force=True)
    if force:
        print(f"   🔄 Force mode enabled - auto-confirming deletion")
        response = 'yes'
    else:
        response = input(f"   ⚠️  Are you sure you want to delete all frames? (yes/no): ")

    if response.lower() in ['yes', 'y']:
        # Remove the entire frames directory
        shutil.rmtree(frames_dir)
        print(f"   ✅ Cleared {total_frames} frames from {len(video_dirs)} videos")
        # Recreate empty directory
        frames_dir.mkdir(parents=True, exist_ok=True)
    else:
        print(f"   ❌ Cancelled - keeping existing frames")
        return False

    return True


def extract_frames_from_video(video_path, output_dir, target_num_frames, fps=None):
    """
    Extract frames from a video file

    Args:
        video_path: Path to video file
        output_dir: Directory to save frames
        target_num_frames: Target number of frames to extract (from H5)
        fps: Optional target FPS for extraction

    Returns:
        Number of frames extracted
    """
    # Open video
    cap = cv2.VideoCapture(str(video_path))

    if not cap.isOpened():
        tqdm.write(f"   ❌ Could not open video: {video_path}")
        return 0

    # Get video properties
    total_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
    video_fps = cap.get(cv2.CAP_PROP_FPS)

    tqdm.write(f"   Video FPS: {video_fps:.2f}, Total frames: {total_frames}, Target: {target_num_frames}")

    # Calculate frame indices to extract
    # Sample uniformly across the video to match H5 features
    if target_num_frames >= total_frames:
        # Extract all frames
        frame_indices = list(range(total_frames))
    else:
        # Sample uniformly
        frame_indices = np.linspace(0, total_frames - 1, target_num_frames, dtype=int)

    # Create output directory
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    # Extract frames
    extracted_count = 0

    for i, frame_idx in enumerate(tqdm(frame_indices, desc="   Extracting frames", unit="frame", leave=False)):
        # Set frame position
        cap.set(cv2.CAP_PROP_POS_FRAMES, frame_idx)

        # Read frame
        ret, frame = cap.read()

        if not ret:
            tqdm.write(f"   ⚠️  Could not read frame {frame_idx}")
            continue

        # Save frame using actual frame index (not sequential index)
        # This matches the frame_id in JSON files (0, 15, 30, 45, ...)
        frame_filename = output_dir / f"frame_{frame_idx:06d}.jpg"
        cv2.imwrite(str(frame_filename), frame, [cv2.IMWRITE_JPEG_QUALITY, 95])
        extracted_count += 1

    cap.release()

    return extracted_count


def process_dataset(dataset_name, h5_path, video_dir, output_base_dir, clear_first=False, force_clear=False):
    """
    Process all videos in a dataset

    Args:
        dataset_name: Name of dataset (ovp, youtube, etc.)
        h5_path: Path to H5 file
        video_dir: Directory containing video files
        output_base_dir: Base directory for frame output
        clear_first: Whether to clear existing frames before processing
        force_clear: If True, skip confirmation when clearing (for automated runs)
    """
    h5_path = Path(h5_path)
    video_dir = Path(video_dir)
    output_base_dir = Path(output_base_dir)

    # Check paths
    if not h5_path.exists():
        print(f"❌ H5 file not found: {h5_path}")
        return

    if not video_dir.exists():
        print(f"❌ Video directory not found: {video_dir}")
        return

    print("="*80)
    print(f"{dataset_name.upper()} Dataset Frame Extraction")
    print("="*80)
    print(f"📂 H5 file: {h5_path}")
    print(f"📂 Video dir: {video_dir}")
    print(f"📂 Output dir: {output_base_dir}")
    print("="*80)
    print()

    # Clear existing frames if requested
    if clear_first:
        result = clear_frames_directory(output_base_dir, force=force_clear)
        if result is False:  # User cancelled
            return
        print()

    # Open H5 file
    with h5py.File(h5_path, 'r') as h5_file:
        video_keys = list(h5_file.keys())
        print(f"Found {len(video_keys)} videos in H5 file\n")

        stats = {
            'total': len(video_keys),
            'success': 0,
            'failed': 0,
            'skipped': 0
        }

        # Process each video
        for video_key in tqdm(video_keys, desc="Processing videos", unit="video"):
            # Get target number of frames from H5
            features = h5_file[video_key]['features']
            target_num_frames = features.shape[0]

            # Find corresponding video file
            video_path = find_video_file(video_dir, video_key, dataset_name)

            if not video_path:
                tqdm.write(f"⚠️  Video file not found for {video_key}")
                stats['failed'] += 1
                continue

            # Check if already processed (only if not clearing)
            output_dir = output_base_dir / video_key
            if not clear_first and output_dir.exists():
                existing_frames = len(list(output_dir.glob("*.jpg")))
                if existing_frames >= target_num_frames * 0.9:
                    tqdm.write(f"✅ Skipping {video_key} - already processed ({existing_frames} frames)")
                    stats['skipped'] += 1
                    continue

            # Extract frames
            tqdm.write(f"\n🎬 Processing {video_key}")
            tqdm.write(f"   Video file: {video_path.name}")

            try:
                extracted = extract_frames_from_video(
                    video_path,
                    output_dir,
                    target_num_frames
                )

                if extracted >= target_num_frames * 0.9:  # Allow 10% tolerance
                    tqdm.write(f"   ✅ Extracted {extracted}/{target_num_frames} frames")
                    stats['success'] += 1
                else:
                    tqdm.write(f"   ⚠️  Only extracted {extracted}/{target_num_frames} frames")
                    stats['failed'] += 1

            except Exception as e:
                tqdm.write(f"   ❌ Error: {e}")
                stats['failed'] += 1

    # Print summary
    print("\n" + "="*80)
    print("Summary")
    print("="*80)
    print(f"Total videos: {stats['total']}")
    print(f"✅ Successfully processed: {stats['success']}")
    print(f"⏭️  Skipped (already done): {stats['skipped']}")
    print(f"❌ Failed: {stats['failed']}")
    print("="*80)


def find_video_file(video_dir, video_key, dataset_name):
    """
    Find video file for a given video key

    Args:
        video_dir: Directory containing videos
        video_key: Video identifier (e.g., 'video_1')
        dataset_name: Dataset name (ovp, youtube, etc.)

    Returns:
        Path to video file or None
    """
    video_dir = Path(video_dir)

    # Extract video number
    video_num = int(video_key.replace('video_', ''))

    # Define naming patterns based on dataset
    if dataset_name.lower() == 'ovp':
        # OVP special mapping: video_1 -> v21.mpg, video_2 -> v22.mpg, etc.
        # Video files are named v21-v70 (corresponding to video_1-video_50)
        actual_num = video_num + 20
        patterns = [
            f"v{actual_num}.mpg",
            f"v{actual_num}.mp4",
            f"v{actual_num}.avi",
            # Also try original number just in case
            f"v{video_num}.mpg",
            f"v{video_num}.mp4",
            f"v{video_num}.avi",
        ]
    elif dataset_name.lower() == 'youtube':
        # YouTube uses a lookup table (no simple pattern)
        # Generated by matching H5 frame counts to video file frame counts
        patterns = []

        if video_num in YOUTUBE_VIDEO_MAPPING:
            actual_num = YOUTUBE_VIDEO_MAPPING[video_num]
            patterns = [
                f"v{actual_num}.flv",
                f"v{actual_num}.avi",
                f"v{actual_num}.mp4",
            ]

        # Fallback: also try direct mapping
        patterns.extend([
            f"v{video_num}.flv",
            f"v{video_num}.avi",
            f"v{video_num}.mp4",
        ])
    else:
        # Generic patterns
        patterns = [
            f"v{video_num}.mp4",
            f"v{video_num}.mpg",
            f"v{video_num}.avi",
            f"v{video_num}.webm",
            f"v{video_num}.mkv",
        ]

    # Add video_key based patterns
    patterns.extend([
        f"{video_key}.mp4",
        f"{video_key}.mpg",
        f"{video_key}.avi",
    ])

    # Try to find the file
    for pattern in patterns:
        candidate = video_dir / pattern
        if candidate.exists():
            return candidate

    return None


def main():
    """主入口函数 - 所有路径从配置文件读取"""
    parser = argparse.ArgumentParser(
        description='Extract frames from videos based on H5 file',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  # Extract frames for OVP dataset
  python 0_extract_frames.py --dataset ovp

  # Extract frames for YouTube dataset
  python 0_extract_frames.py --dataset youtube

  # Clear existing frames before extraction
  python 0_extract_frames.py --dataset ovp --clear

注意：所有路径从配置文件读取，请确保已正确设置 configs/config.yaml
        """
    )

    # Get script directory for computing absolute paths
    script_dir = Path(__file__).resolve().parent
    project_root = script_dir.parent.parent

    parser.add_argument('--dataset', type=str, required=True,
                       choices=['ovp', 'youtube', 'summe', 'tvsum', 'videoxum', 'mrhisum'],
                       help='Dataset to process')
    parser.add_argument('--clear', action='store_true',
                       help='Clear existing frames before extraction')

    args = parser.parse_args()

    # 从配置读取路径（纯配置，无回退）
    dataset_name = args.dataset.lower()

    import sys
    if str(project_root) not in sys.path:
        sys.path.insert(0, str(project_root))
    from utils.config_loader import get_config
    config = get_config()
    ds_paths = config.get_dataset_paths(dataset_name)

    h5_path = ds_paths.get('h5_file')
    video_dir = ds_paths.get('videos_dir')
    output_dir = ds_paths.get('frames_dir')

    if not h5_path:
        raise ValueError(f"配置文件中未定义 {dataset_name}.h5_file")
    if not video_dir:
        raise ValueError(f"配置文件中未定义 {dataset_name}.videos_dir")
    if not output_dir:
        raise ValueError(f"配置文件中未定义 {dataset_name}.frames_dir")

    # Process dataset
    process_dataset(
        dataset_name,
        h5_path,
        video_dir,
        output_dir,
        clear_first=args.clear
    )


if __name__ == "__main__":
    main()
